        auto source = edge.first->vertex((edge.second + 1) % 3)->info();
        auto target = edge.first->vertex((edge.second + 2) % 3)->info();
        if (source > target) std::swap(source, target);
        edges.emplace_back(source, target);
    }

    // Remove duplicate edges
    std::sort(edges.begin(), edges.end());
    edges.erase(std::unique(edges.begin(), edges.end()), edges.end());

    // Compute alpha shape edges
    std::vector<bool> is_alpha_edge(edges.size(), false);
    for (std::size_t i = 0; i < edges.size(); ++i) {
        auto edge = edges[i];
        auto v1 = unique_points[edge.first];
        auto v2 = unique_points[edge.second];

        // Get the circumradius of the edge's incident triangles
        auto handle = dt.edge_circulator(dt.segment(edge.first, edge.second));
        auto start = handle;
        double min_circumradius = std::numeric_limits<double>::max();

        do {
            auto triangle = *handle;
            auto face = triangle.first;
            auto vertices = std::array<std::size_t, 3>{
                face->vertex(0)->info(),
                face->vertex(1)->info(),
                face->vertex(2)->info()
            };

            // Find the third vertex
            std::size_t third_vertex = vertices[0];
            if (third_vertex == edge.first || third_vertex == edge.second) third_vertex = vertices[1];
            if (third_vertex == edge.first || third_vertex == edge.second) third_vertex = vertices[2];

            // Compute circumradius
            auto p1 = unique_points[edge.first];
            auto p2 = unique_points[edge.second];
            auto p3 = unique_points[third_vertex];
            double circumradius = CGAL::circumradius(p1, p2, p3);

            if (circumradius < min_circumradius) {
                min_circumradius = circumradius;
            }
        } while (++handle != start);

        // Check if edge is in alpha shape
        if (min_circumradius <= alpha) {
            is_alpha_edge[i] = true;
        }
    }

    // Build adjacency list for alpha shape edges
    std::vector<std::vector<std::size_t>> adj(unique_points.size());
    for (std::size_t i = 0; i < edges.size(); ++i) {
        if (is_alpha_edge[i]) {
            auto edge = edges[i];
            adj[edge.first].push_back(edge.second);
            adj[edge.second].push_back(edge.first);
        }
    }

    // Count connected components
    std::vector<bool> visited(unique_points.size(), false);
    int component_count = 0;

    for (std::size_t i = 0; i < unique_points.size(); ++i) {
        if (!visited[i]) {
            std::queue<std::size_t> q;
            q.push(i);
            visited[i] = true;

            while (!q.empty()) {
                auto current = q.front();
                q.pop();

                for (auto neighbor : adj[current]) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        q.push(neighbor);
                    }
                }
            }
            component_count++;
        }
    }

    return component_count;

